import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { VERSION_SOURCE, versionFromLiteral, compareVersions, versionsEqual, nextVersion } from '../../../../engine/version.mjs';

// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
// engine tree vendors wholesale on every converge; a pack's directory ships only
// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`
// (updates/pack-update.mjs). So a canon commit that edits `packs/<id>/` without
// touching that number lands here, goes green here, and reaches no member — the
// fleet keeps the old bytes while canon believes the change shipped.
//
// #939 is what that costs. A check vocabulary rename updated the engine and the
// canon's own packs in one commit: the engine, delivered unconditionally, reached
// every member and rejected the old spelling; the pack carrying the new spelling
// stayed at `version: 1` and reached nobody. The mixed tree failed each member's
// self-test, the update PR parked, and the fix could not arrive by the route that
// delivers fixes. Seven repos sat frozen for five days.
//
// So the invariant this rule holds is one line: A CHANGE UNDER `packs/<id>/` IS A
// CHANGE TO THAT PACK'S VERSION. Every SHIPPING byte counts, because every one of
// them rides the same directory copy — prose, a skill, a check module, a migration
// record. A pack's tests sit beside the files they cover and are the one thing in
// that directory no vendor set carries (compute-vendor-set drops `*.test.mjs`), so
// nobody is waiting on them and a bump for one would re-deliver every pack in the
// tree to say nothing.
// It is the pack-side twin of `engine-release-record` (the claudinite local pack),
// which holds the same line for `ENGINE_VERSION`.
//
// WORK SCOPE: the question is what THIS change did. The tree always contains a
// version number; only the diff says whether it moved with the content beside it.
const LOCAL_PACKS = '.claudinite/local/packs';

// Each pack's version-bump log, next to its manifest — see `versionRecorded`
// below for what it must carry once a bump lands.
export const VERSIONS_FILENAME = 'VERSIONS.md';

// The pack ids a changed-file list touches, in first-seen order. Anchored at
// `packs/<id>/` so the canon's own local packs (which vendor nowhere, carry no
// version and reach no member) and the tree's own files (`packs/README.md`,
// `packs/directory.GENERATED.md`) are outside it by construction. Tests drop out for
// the same reason the local packs do: nothing delivers them. `VERSIONS.md` drops
// out too — it is the log OF bumps, not content a bump ships, so editing it alone
// (recording a bump made elsewhere in the same change, or a wording fix to an old
// row) must never itself demand another bump.
export function packsTouched(changed) {
  const ids = [];
  for (const file of changed ?? []) {
    if (file.startsWith(`${LOCAL_PACKS}/`) || file.endsWith('.test.mjs') || file.endsWith(`/${VERSIONS_FILENAME}`)) continue;
    const m = /^packs\/([^/]+)\//.exec(file);
    if (m && !ids.includes(m[1])) ids.push(m[1]);
  }
  return ids;
}

// The `version:` a pack manifest declares, or null when it declares none (a
// manifest that is absent on one side of the diff, or one the schema check owns).
// The preceding-character class is what keeps `minEngineVersion:` out of it.
const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[\s{,])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
export function declaredPackVersion(text) {
  const m = PACK_VERSION_RE.exec(text ?? '');
  return m ? versionFromLiteral(m[1]) : null;
}

// Does the pack's VERSIONS.md carry a row for this version? A row is a table row
// whose first cell is the bare version — the same shape `engine/RELEASES.md`
// rows use, so the log reads as a table a human maintains, not a format this
// check invented. No run link is required here (unlike an engine release): a
// pack bump has no canary rehearsal to cite, so the row's own prose is the
// record.
const ROW_VERSION_RE = new RegExp(String.raw`^\|\s*(${VERSION_SOURCE})\s*\|`);
export function versionRecorded(text, version) {
  for (const line of (text ?? '').split('\n')) {
    const m = ROW_VERSION_RE.exec(line.trim());
    if (m && versionsEqual(versionFromLiteral(m[1]), version)) return true;
  }
  return false;
}

const rule = {
  id: 'pack-version-bumped',
  severity: 'blocking',
  scope: 'work',
  description: 'A change under packs/<id>/ bumps that pack\'s version, and a bump lands with its VERSIONS.md row',
  doc: 'docs/versioned-updates/DESIGN.md',
  why: 'a member receives a pack directory only when the canon\'s version exceeds the one it has installed, so content edited without a bump reaches nobody while canon CI reports it shipped (#939 froze seven repos for five days that way); an unrecorded bump is the same evidence gap on a smaller scale — "what did version N change?" becomes unanswerable once the commit scrolls out of history',

  run(work) {
    const findings = [];
    for (const id of packsTouched(work.changedFiles)) {
      const manifest = `packs/${id}/pack.mjs`;
      const head = declaredPackVersion(work.read(manifest));
      if (head === null) continue;                     // the pack was deleted, or declares no version — other rules own that
      const base = declaredPackVersion(work.readBase(manifest));
      if (base === null) continue;                     // a pack this change introduces: its first version ships to everyone
      const moved = compareVersions(head, base);

      if (moved <= 0) {
        findings.push(finding(rule, {
          file: manifest,
          what: moved === 0
            ? `this change edits packs/${id}/ but leaves its version at ${head}`
            : `packs/${id}/ moves its version backwards, ${base} → ${head}`,
          fix: moved === 0
            ? `raise \`version\` in ${manifest} to '${nextVersion(base)}' — the version is the whole delivery signal, so an edit `
              + 'that does not move it stays in the canon forever'
            : 'pack versions only ever increase — the update flow reads them as an ordering, so a lowered number tells '
              + 'every member it is already up to date',
        }));
        continue;
      }

      const versionsFile = `packs/${id}/${VERSIONS_FILENAME}`;
      if (!versionRecorded(work.read(versionsFile), head)) {
        findings.push(finding(rule, {
          file: versionsFile,
          what: `packs/${id}/ bumps its version to ${head}, and ${versionsFile} carries no row for it`,
          fix: `add a row to ${versionsFile} for version ${head} saying what changed`,
        }));
      }
    }
    return findings;
  },
};

export default rule;

// claudinite-growth task: growth-extract — the growth lifecycle's CAPTURE
// stage (per-project-scheduling DESIGN §6). ONE task over BOTH lesson sources:
// it runs the extract-from-activity skill over the window's commits/PRs/issues
// and the extract-from-conversations skill over the captured conversation logs,
// then runs prose-to-checks over what it just wrote to see whether any of it
// upgrades to a check — and lands the whole run through a single PR delivered
// per the repo's delivery settings (task.md → the shared deliver-pr.md
// procedure). Worker: task.md.
//
// The two halves were separate tasks (growth-extract + conversation-extract)
// firing at the same daily anchor, each opening its own PR against the same local
// packs on the same night. They shared the lesson bar, the promotion ladder, the
// dedup surface and the landing mechanics, so splitting them bought nothing and
// cost a second opus dispatch, a second PR, and two runs deduping against a
// corpus the other one was concurrently writing. One task, two source skills.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-extract',
  frequency: 'daily-1h',           // the 03:00 anchor — lessons captured from an already-converged mount (DESIGN §2)
  // …and the ordering the anchor hour only IMPLIES, declared (tasks-dispatch
  // DESIGN §9): this task reads a mount `claudinite-lifecycle/update` converges, so it yields while
  // that task's item is live this cycle and runs the moment it converges — or
  // rolls. The staggered anchor hours express the same intent and cannot enforce
  // it; this can.
  after: ['claudinite-lifecycle/update'],
  precondition_signals: ['commits', 'prs', 'issues'],
  agent_model: 'opus',                   // generalizing/curating lessons is the heaviest judgment, and the default delivery lands the PR with no human review
  expected_outcome: 'merged-pr',            // additive edits to the repo's own local packs; delivered to land per the repo's delivery settings
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,            // two source passes plus the prose-to-checks upgrade — generous bound, extreme protection

  // ONE reason to run: a SUBSTANTIVE default-branch change. A bot bump / [skip ci] /
  // nightly-baselining commit advancing main is not a lesson to extract, and neither
  // is a commit that touched nothing outside `.claudinite/` — this lifecycle's own
  // landed output, which would otherwise re-arm it every night and keep a quiet repo
  // firing forever. `commits.substantiveChange` already applies that classification.
  // It arms the activity half AND means a fresh capture now sits on the logs branch,
  // so the conversation half runs too.
  //
  // There WAS a second arm — a log actually past retention, which existed only so
  // the retention prune still fired on a repo gone quiet. The prune is its own
  // agentless task now (../logs-prune/), so that arm left with it and this opus
  // dispatch no longer happens on nights with nothing to extract.
  //
  // The activity half is scoped by the substantive shas + touched PR/issue numbers
  // passed as binding scope — INCLUDING the PRs merged during the window, whose
  // review discussion is usually its richest lesson source. Context is binding
  // scope and task.md forbids widening past it, so a merged PR the precondition
  // does not name is unreadable to the worker.
  precondition(signals) {
    const commits = signals.commits ?? {};
    if (commits.substantiveChange !== true) {
      return { run: false, reason: 'no substantive default-branch change in the window — nothing to extract' };
    }

    const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
    const prs = signals.prs?.touched ?? [];
    const merged = (signals.prs?.merged ?? []).map((p) => p.number);
    const issues = signals.issues?.touched ?? [];

    const context = [`Activity half IS in scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`];
    if (merged.length) context.push(`PRs merged in the window — read each one's diff and its review discussion: ${merged.map((n) => `#${n}`).join(', ')}.`);
    if (prs.length) context.push(`PRs touched in the window: ${prs.map((n) => `#${n}`).join(', ')}.`);
    if (issues.length) context.push(`Issues touched in the window: ${issues.map((n) => `#${n}`).join(', ')}.`);
    context.push('Conversation half IS in scope: a substantive merge means fresh captures on origin/conversation-logs — run the fresh pass over the recent window.');

    return { run: true, reason: `${shas.length} substantive commit(s) in the window`, context };
  },
};

